# POST /api/sheets/{sheetId}/generate-periods — make one period per calendar month from the from-date's
# month to the to-date's month, leaving out a month whose name is taken or whose days overlap a period.
# A to-date before the from-date is refused. Responds with how many were made.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: generate
generate:
  class: net.officefloor.hq.app.period.GeneratePeriods
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithGeneratedPeriods
# POST /api/sheets/{sheetId}/settings — change a setting; an unknown key or a bad value is refused.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.setting.ValidateSetting
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: set
set:
  class: net.officefloor.hq.app.setting.ChangeSetting
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.setting.RecordSettingChanged
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.setting.RespondWithSetting
# GET /api/sheets/{sheetId}/periods — the sheet's periods, by from-date.
list:
  class: net.officefloor.hq.app.period.ListPeriods
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/** Makes one period per calendar month from the from-date's month to the to-date's month, each from
 *  the first to the last day of its month and named yyyy-MM, each recorded as PERIOD_ADDED. A month
 *  whose name is already a period, or whose days overlap a period on the sheet, is left out. A
 *  to-date before the from-date is refused and nothing is written. */
public class GeneratePeriods {
    public void generate(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by,
            @RequestBody GeneratePeriodsRequest request, SheetRepository sheets, PeriodRepository periods,
            Audit audit, Out<GeneratePeriodsResult> result) throws InvalidPeriodException {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        LocalDate today = sheets.today(id);
        LocalDate from = date(request == null ? null : request.from(), today);
        LocalDate to = date(request == null ? null : request.to(), today);
        if (to.isBefore(from)) {
            throw new InvalidPeriodException("The to-date must be on or after the from-date");
        }
        sheets.open(id, user);
        int made = 0;
        for (YearMonth m = YearMonth.from(from); !m.isAfter(YearMonth.from(to)); m = m.plusMonths(1)) {
            String name = m.toString();
            LocalDate first = m.atDay(1);
            LocalDate last = m.atEndOfMonth();
            if (periods.nameTaken(id, name) || periods.overlaps(id, first, last)) continue;
            Period period = periods.add(id, name, first, last, user);
            audit.record("PERIOD_ADDED sheet=" + id + " by=" + user + " period=" + period.name()
                    + " from=" + period.from() + " to=" + period.to());
            made++;
        }
        result.set(new GeneratePeriodsResult(made));
    }

    private static LocalDate date(String text, LocalDate blank) throws InvalidPeriodException {
        String t = text == null ? "" : text.trim();
        if (t.isEmpty()) return blank;
        try {
            return LocalDate.parse(t);
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("Not a date: " + t);
        }
    }
}
package net.officefloor.hq.app.period;

/** Body of generating monthly periods: a from-date and a to-date (yyyy-MM-dd); a blank one is the sheet's today. */
public record GeneratePeriodsRequest(String from, String to) {
}
package net.officefloor.hq.app.period;

/** How many monthly periods were made. */
public record GeneratePeriodsResult(int made) {
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithGeneratedPeriods {
    public void respond(@Val GeneratePeriodsResult result, ObjectResponse<GeneratePeriodsResult> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.period;

import java.util.Map;

/** A period on a sheet: its name and its from and to dates (yyyy-MM-dd), both inclusive, whether it
 *  is closed and, once closed, its due-total fixed at that moment (two decimals) and each person's
 *  due-total for it fixed then too, by person id (a person not in it shows 0.00). A soft-closed period
 *  ({@code soft}, not {@code closed}) has its figures fixed the same way, but claims due by a day in it can
 *  still be added and changed. */
public record Period(String sheetId, String name, String from, String to, boolean closed,
        String closedTotal, Map<Long, String> personTotals, boolean soft) {

    /** Whether its figures are fixed: closed or soft-closed. */
    public boolean fixed() {
        return closed || soft;
    }

