import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { useSheetToday } from '../sheet/api';
import { poolsKey } from '../pools/api';
import { ratesKey } from '../rates/api';
import { changeSetting, listSettings, PERMISSION_STANDING, settingOn, settingsKey, SETTING_KEYS, UNDATED_KEYS } from './api';

/** The sheet's settings: each one's value in force on the sheet's today and a form that changes them.
 *  A field shows the value in force until it is edited; saving saves the fields entered (every field
 *  when none was), a dated one from its from-date (blank: the sheet's today). */
export function Settings({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
  const today = useSheetToday(sheetId, user);
  const current = (key: string) => settingOn(settings.data, key, today) ?? '';
  const [form, setForm] = useState<Record<string, string>>({});
  const [froms, setFroms] = useState<Record<string, string>>({});

  const save = useMutation({
    mutationFn: async ({ values, from }: { values: Record<string, string>; from: Record<string, string> }) => {
      for (const [key, value] of Object.entries(values)) await changeSetting(sheetId, user, key, value, from[key] ?? '');
    },
    onSettled: () => Promise.all([
      queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) }),
      queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) }),
      queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) }),
    ]),
  });

  const submitOnce = useSubmitOnce();

  const enter = (key: string) => setForm((f) => (key in f ? f : { ...f, [key]: current(key) }));

  const change = (key: string, value: string) => {
    setForm((f) => ({ ...f, [key]: value }));
    save.reset();
  };

  // A from-date entered alone saves the value in force from it.
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.HashSet;
import java.util.Set;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class ChangeSetting {
    public void set(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by,
            @Val SettingRequest request, SheetRepository sheets, SettingRepository settings,
            RateRepository rates, Out<Setting> setting) throws InvalidSettingException {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        if (SettingRepository.PARENT.equals(request.key()) && request.value() != null) {
            String parent = request.value();
            if (parent.equals(id)) {
                throw new InvalidSettingException("A sheet cannot be its own parent");
            }
            if (sheets.find(parent) == null) {
                throw new InvalidSettingException("The parent must be a sheet that exists");
            }
            // Walk up from the parent: meeting this sheet would make a cycle.
            Set<String> seen = new HashSet<>();
            for (String at = rates.parent(parent); at != null && seen.add(at); at = rates.parent(at)) {
                if (at.equals(id)) {
                    throw new InvalidSettingException("The parent cannot be a sheet that has this sheet as an ancestor");
                }
            }
        }
        sheets.open(id, user);
        // A dated key's value applies from its from-date, by default the sheet's today.
        LocalDate from = !SettingRepository.isDated(request.key()) ? null
                : request.from() != null ? LocalDate.parse(request.from()) : sheets.today(id);
        setting.set(settings.set(id, request.key(), request.value(), from, user));
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a change that went through is recorded (with its from-date when one was given). */
public class RecordSettingChanged {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Setting setting, @Val SettingRequest request, Audit audit) {
        audit.record("SETTING_CHANGED sheet=" + setting.sheetId() + " by=" + (by == null ? "" : by)
                + " key=" + setting.key() + " value=" + setting.value()
                + (request.from() == null ? "" : " from=" + request.from()));
    }
}

